CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE categories (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(80) NOT NULL,
    CONSTRAINT "PK_categories" PRIMARY KEY ("Id")
);

CREATE TABLE courses (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" character varying(150) NOT NULL,
    "ShortName" character varying(60) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "CategoryId" integer NOT NULL,
    "Modality" character varying(20) NOT NULL,
    "WorkloadHours" integer NOT NULL,
    "TargetAudience" character varying(300) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "ImageUrl" character varying(500) NOT NULL,
    "AvailableFrom" date,
    CONSTRAINT "PK_courses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_courses_categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES categories ("Id") ON DELETE RESTRICT
);

CREATE TABLE topics (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CourseId" integer NOT NULL,
    "Order" integer NOT NULL,
    "Title" character varying(150) NOT NULL,
    "Description" character varying(1000),
    CONSTRAINT "PK_topics" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_topics_courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES courses ("Id") ON DELETE CASCADE
);

CREATE TABLE lessons (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TopicId" integer NOT NULL,
    "Order" integer NOT NULL,
    "Title" character varying(150) NOT NULL,
    "Description" character varying(1000) NOT NULL,
    "DurationMinutes" integer NOT NULL,
    CONSTRAINT "PK_lessons" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_lessons_topics_TopicId" FOREIGN KEY ("TopicId") REFERENCES topics ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_categories_Name" ON categories ("Name");

CREATE INDEX "IX_courses_CategoryId" ON courses ("CategoryId");

CREATE INDEX "IX_lessons_TopicId" ON lessons ("TopicId");

CREATE INDEX "IX_topics_CourseId" ON topics ("CourseId");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261022212532_InitialCreate', '10.0.13');

COMMIT;

START TRANSACTION;
ALTER TABLE courses ADD "Slug" character varying(120) NOT NULL DEFAULT '';

CREATE UNIQUE INDEX "IX_courses_Slug" ON courses ("Slug");

